import os
import six

from lxml import etree, objectify
from logging import getLogger

from .exception import ScfcValidationError


log = getLogger('ute_btssm.scfc')


class SCFCValidator(object):

    RELATIVE_JAVA_PATH_TEMPLATE = './jre/{version}/bin/java'

    def __init__(self, executor, btssm_cmd_builder, temp_path):
        """
        :param Executor executor: Object which is able to execute commands remotely.
        :param BTSSMCommandBuilder btssm_cmd_builder: Object which is able to build BTSSM execution commands.
        :param string temp_path: Temporary directory.
        """
        self._executor = executor
        self._temp_path = temp_path
        self._btssm_cmd_builder = btssm_cmd_builder
        self._btssm_install_location = btssm_cmd_builder.install_location

    def copy_scfc(self, local_scfc_path):
        """Copy provided file to remote location.

        :param string local_scfc_path: Path to SCFC file available locally.

        :return: Path to new remote location.
        :rtype: string
        """
        new_path = os.path.join(self._temp_path, 'SCFC.xml')
        return self._executor.put_file(local_scfc_path, new_path)

    def run_validation(self, remote_scfc_path, version):
        """Generate validation feedback.

        :param string remote_scfc_path: Path to SCFC file.
        :param string version: Validator version.

        :return: Path to new feedback file.
        :rtype: string
        """
        java_path = self._select_java_path(version)
        log.debug("Selected java path: {}".format(java_path))
        feedback_path = os.path.join(self._temp_path, 'feedback.xml')
        log.debug("version:{}".format(version))
        cmd = self._build_validation_cmd(java_path, remote_scfc_path, feedback_path, version)
        self._executor.run_ignoring_rc(cmd)
        return feedback_path

    def get_file(self, remote_path, local_path):
        """Get file from remote location.

        :param string remote_path: Path to file on remote machine.
        :param string local_path: Path to file on local machine.

        :return: Execution result.
        :rtype: string
        """
        return self._executor.get_file(remote_path, local_path)

    def check_validation_result(self, local_feedback_path):
        """Check if feedback file has possitive result.

        :param string local_feedback_path: Path to feedback file.

        :raise: ScfcValidationError if feedback file contains negative result of validation.
        """
        tree = objectify.parse(local_feedback_path)
        root = tree.getroot()
        items = root.findall('.//{*}message/{*}p[@name="status"]')
        for item in items:
            if item.text.strip().lower() == 'error':
                raise ScfcValidationError("Validation discovered some errors.")
        return

    def get_version(self, local_scfc_path):
        """Get validator version.

        :param string local_scfc_path: Path to SCFC file.

        :return: Validator version.
        :rtype: string
        """
        try:
            return self._get_version_from_scfc(local_scfc_path)
        except IndexError:
            return None

    def _get_version_from_scfc(self, local_scfc_path):
        with open(local_scfc_path, "r") as f:
            xml = f.read() if six.PY2 else f.read().encode()
        return etree.fromstring(xml).xpath('.//*[contains(@class, "LNBTS")]/@version')[0].split('_')[0]

    def _build_validation_cmd(self, java_path, scfc_path, feedback_path, version):
        params = {'planfile': '"%s"' % scfc_path,
                  'feedbackfile': '"%s"' % feedback_path,
                  'prevalidation': version}
        return self._btssm_cmd_builder.build(java_path=java_path, params=params)

    def _select_java_path(self, version):
        enb_builds = ['FL00', 'FL16', 'FL16A', 'FL15A']
        out = self._executor.run_ignoring_rc('cd "{}"; ls -1 ./jre/'.format(self._btssm_install_location)).strip().split('\n')
        if len(out) == 1 and out[0].strip():
            return SCFCValidator.RELATIVE_JAVA_PATH_TEMPLATE.format(version=out[0].strip())
        elif version in enb_builds:
            return SCFCValidator.RELATIVE_JAVA_PATH_TEMPLATE.format(version='1_8_0')
        else:
            return SCFCValidator.RELATIVE_JAVA_PATH_TEMPLATE.format(version='1_7_0')
